package com.personal.gridbot.amaros.design

/** Primary AMAR AI visual identity controller; UI-only and authority-neutral. */
object AmarAiOrbController {
    fun script(): String = """
        (function(){
          var a=document.querySelector('.core'); if(!a)return;
          a.id='amarAiOrb';
          a.setAttribute('role','button');
          a.setAttribute('aria-label','AMAR AI — Central Intelligence');
          a.innerHTML='<span class="ai-core-title">AMAR AI</span><span class="ai-core-sub">CENTRAL INTELLIGENCE</span><span class="ai-core-state">● ONLINE · READY</span><span class="ai-ring r1"></span><span class="ai-ring r2"></span><span class="ai-ring r3"></span><span class="ai-orbit o1"></span><span class="ai-orbit o2"></span><span class="ai-orbit o3"></span><span class="ai-particle p1"></span><span class="ai-particle p2"></span><span class="ai-particle p3"></span><span class="ai-particle p4"></span><span class="ai-sheen"></span>';
          a.onclick=function(){if(window.Android&&Android.openRoom)Android.openRoom('AMAR_AGENT')};
          var s=document.getElementById('amarAiPremiumStyle'); if(s)s.remove();
          s=document.createElement('style');s.id='amarAiPremiumStyle';
          s.textContent=`
          #amarAiOrb{position:absolute!important;inset:10%!important;width:auto!important;height:auto!important;border:1px solid rgba(255,255,255,.62)!important;border-radius:50%!important;background:radial-gradient(circle at 31% 23%,#fff 0%,#bdfaff 8%,#36dfff 23%,#6357ff 48%,#d735ff 72%,#080316 100%)!important;box-shadow:0 0 0 4px rgba(255,255,255,.10),0 0 22px #28ddff,0 0 50px rgba(108,77,255,.78),0 0 90px rgba(220,53,255,.38),inset 10px 10px 25px rgba(255,255,255,.52),inset -14px -16px 30px rgba(5,0,28,.76)!important;overflow:visible!important;isolation:isolate;cursor:pointer;animation:amarAiFloat 4.8s ease-in-out infinite}
          #amarAiOrb:before{content:'';position:absolute;inset:-7px;border-radius:50%;background:conic-gradient(from 0deg,#00eaff,#7c5cff,#ff3fdf,#00eaff);filter:blur(3px);opacity:.72;z-index:-1;animation:amarAiRainbow 5.2s linear infinite}
          #amarAiOrb:after{content:'';position:absolute;inset:-17px;border-radius:50%;border:1px solid rgba(74,230,255,.34);box-shadow:0 0 28px rgba(74,230,255,.30),0 0 55px rgba(215,55,255,.18);z-index:-2;animation:amarAiPulse 2.7s ease-in-out infinite}
          #amarAiOrb .ai-core-title{position:relative;z-index:12;font:1000 clamp(25px,8vw,40px)/1 Arial,sans-serif;letter-spacing:1.8px;color:#fff;text-shadow:0 0 7px #fff,0 0 16px #00eaff,0 0 28px #c83dff,0 0 42px #ff4bdc;animation:amarAiText 1.9s ease-in-out infinite}
          #amarAiOrb .ai-core-sub{position:relative;z-index:12;margin-top:7px;font:900 clamp(7px,2vw,10px)/1.1 Arial,sans-serif;letter-spacing:1.6px;color:#dffcff;text-shadow:0 0 8px #00eaff;text-align:center}
          #amarAiOrb .ai-core-state{position:relative;z-index:12;margin-top:11px;padding:6px 11px;border:1px solid rgba(255,255,255,.38);border-radius:18px;background:rgba(2,9,18,.54);font:900 7px/1 Arial,sans-serif;letter-spacing:1px;color:#aaffee;box-shadow:0 0 14px rgba(0,230,180,.20)}
          #amarAiOrb .ai-ring{position:absolute;border-radius:50%;border:1px solid;pointer-events:none;z-index:4}.r1{inset:6%;border-color:rgba(0,239,255,.52);animation:amarAiRing 4s linear infinite}.r2{inset:13%;border-color:rgba(255,73,236,.42);animation:amarAiRingReverse 3.2s linear infinite}.r3{inset:22%;border-color:rgba(255,255,255,.24);animation:amarAiRing 2.4s linear infinite}
          #amarAiOrb .ai-orbit{position:absolute;width:8px;height:8px;border-radius:50%;z-index:9;box-shadow:0 0 10px 3px currentColor;pointer-events:none}.o1{background:#00f6ff;color:#00f6ff;animation:amarAiOrbit1 2.8s linear infinite}.o2{background:#ff48ff;color:#ff48ff;animation:amarAiOrbit2 3.7s linear infinite}.o3{background:#fff;color:#fff;animation:amarAiOrbit3 4.6s linear infinite}
          #amarAiOrb .ai-particle{position:absolute;width:3px;height:3px;border-radius:50%;background:#fff;box-shadow:0 0 8px 2px #00eaff;z-index:10;animation:amarAiParticle 2.6s ease-in-out infinite}.p1{left:15%;top:28%}.p2{right:16%;top:38%;animation-delay:.5s!important}.p3{left:30%;bottom:17%;animation-delay:1s!important}.p4{right:27%;bottom:23%;animation-delay:1.5s!important}
          #amarAiOrb .ai-sheen{position:absolute;width:34%;height:15%;left:10%;top:10%;border-radius:50%;background:rgba(255,255,255,.78);filter:blur(7px);transform:rotate(-35deg);z-index:13;pointer-events:none;animation:amarAiSheen 2.9s ease-in-out infinite}
          #amarAiOrb.market-buy{box-shadow:0 0 0 4px rgba(255,255,255,.10),0 0 calc(22px + 36px * var(--ai-market-intensity)) #35ffb0,0 0 55px rgba(41,255,176,.55),inset 10px 10px 25px rgba(255,255,255,.52),inset -14px -16px 30px rgba(0,40,28,.72)!important}#amarAiOrb.market-sell{box-shadow:0 0 0 4px rgba(255,255,255,.10),0 0 calc(22px + 36px * var(--ai-market-intensity)) #ff4d7d,0 0 55px rgba(255,55,112,.55),inset 10px 10px 25px rgba(255,255,255,.52),inset -14px -16px 30px rgba(55,0,20,.72)!important}#amarAiOrb.market-neutral{box-shadow:0 0 0 4px rgba(255,255,255,.10),0 0 22px #39d9ff,0 0 50px rgba(108,77,255,.72),inset 10px 10px 25px rgba(255,255,255,.52),inset -14px -16px 30px rgba(5,0,28,.76)!important}
          @keyframes amarAiFloat{0%,100%{transform:translateY(0) scale(1)}50%{transform:translateY(-6px) scale(1.012)}}@keyframes amarAiRainbow{to{transform:rotate(360deg)}}@keyframes amarAiPulse{50%{transform:scale(1.08);opacity:.48}}@keyframes amarAiText{50%{filter:brightness(1.32);transform:scale(1.035)}}@keyframes amarAiRing{to{transform:rotate(360deg) scale(1.025)}}@keyframes amarAiRingReverse{to{transform:rotate(-360deg) scale(.975)}}@keyframes amarAiOrbit1{from{transform:rotate(0deg) translateX(39%)}to{transform:rotate(360deg) translateX(39%)}}@keyframes amarAiOrbit2{from{transform:rotate(120deg) translateX(33%)}to{transform:rotate(-240deg) translateX(33%)}}@keyframes amarAiOrbit3{from{transform:rotate(210deg) translateX(44%)}to{transform:rotate(-150deg) translateX(44%)}}@keyframes amarAiParticle{50%{transform:translate(7px,-9px) scale(1.8);opacity:.35}}@keyframes amarAiSheen{0%,100%{transform:translate(-5px,-5px) rotate(-35deg);opacity:.22}50%{transform:translate(40px,35px) rotate(-35deg);opacity:.9}}
          @media(prefers-reduced-motion:reduce){#amarAiOrb,#amarAiOrb:before,#amarAiOrb:after,#amarAiOrb .ai-core-title,#amarAiOrb .ai-ring,#amarAiOrb .ai-orbit,#amarAiOrb .ai-particle,#amarAiOrb .ai-sheen{animation-duration:.001ms!important;animation-iteration-count:1!important}}
          `;document.head.appendChild(s);
          window.amarAiOrbSetMarketState=function(direction,intensity,quality){if(!a)return;var i=Math.max(0,Math.min(1,Number(intensity)||0));a.style.setProperty('--ai-market-intensity',i.toFixed(3));a.dataset.marketDirection=direction||'unknown';a.dataset.marketQuality=quality||'unavailable';a.classList.remove('market-buy','market-sell','market-neutral');if(quality==='live'&&direction==='buy')a.classList.add('market-buy');else if(quality==='live'&&direction==='sell')a.classList.add('market-sell');else a.classList.add('market-neutral')};
          window.amarAiOrbSetMarketState('unknown',0,'unavailable');
        })();
    """.trimIndent()
}
